  ('convocatoria_gira', 'ALTA:presente', 'Ausente → presente', 'Alta en gira | {gira}', '{"titulo_interno":"Alta en gira","lead":"Volviste a ser dado/a de <strong>alta</strong> en la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Habías solicitado ser cubierto/a pero ya no es necesario.","cierre":"Saludos.","link_texto":"Ver repertorio y material","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
  ('convocatoria_gira', 'ALTA:cobertura', 'Alta por cobertura (quien cubre)', 'Alta en gira | {gira}', '{"titulo_interno":"Alta en gira","lead":"Fuiste dado/a de <strong>alta</strong> en la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Se te convoca para cubrir a {titular} en esta gira","cierre":"Saludos.","link_texto":"Ver repertorio y material","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
  ('convocatoria_gira', 'ALTA:restituir_titular', 'Restituir titular tras cobertura', 'Alta en gira | Anulación de cobertura | {gira}', '{"titulo_interno":"Alta en gira","lead":"Fuiste dado/a de <strong>alta</strong> en la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Se te restituye en la gira. Quedás nuevamente convocado/a como presente; {quien_cubre} deja de cubrirte y sale de la nómina.","cierre":"Saludos.","link_texto":"Ver repertorio y material","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
