  ('convocatoria_gira', 'AUSENTE', 'Marcar ausente', 'Ausencia en gira | {motivo} | {gira}', '{"titulo_interno":"Ausencia en gira","lead":"Se registró tu situación de <strong>ausente</strong> en la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Se te marcó como ausente. Motivo: {motivo}","cierre":"Para cualquier cambio, contactá a la administración.","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
