  ('convocatoria_gira', 'BAJA:exclusion_familia', 'Exclusión de familia', 'Baja en la gira | Se excluyó la familia | {gira}', '{"titulo_interno":"Baja de gira","lead":"Se registró tu <strong>baja</strong> de la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Se excluyó la familia de {familia}. Motivo: {motivo}","cierre":"Si tenés dudas, respondé a este correo.","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
  ('convocatoria_gira', 'BAJA:cobertura_fin', 'Fin de cobertura (cambio o retiro)', 'Baja de gira | {gira}', '{"titulo_interno":"Baja de gira","lead":"Se registró tu <strong>baja</strong> de la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Fin de cobertura de {titular}.","cierre":"Si tenés dudas, respondé a este correo.","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
  ('convocatoria_gira', 'BAJA:restituir_cubre', 'Baja del cubridor al restituir titular', 'Baja de gira | Anulación de cobertura | {gira}', '{"titulo_interno":"Baja de gira","lead":"Se registró tu <strong>baja</strong> de la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Finalizó tu cobertura en esta gira. {titular} vuelve a la nómina; ya no se requiere tu participación.","cierre":"Si tenés dudas, respondé a este correo.","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
  ('convocatoria_gira', 'BAJA:ambos_titular', 'Baja de ambos — titular', 'Baja de gira | {gira}', '{"titulo_interno":"Baja de gira","lead":"Se registró tu <strong>baja</strong> de la gira <strong>{gira}</strong> ({nomenclador}).","reason":"Baja de la gira: no se requiere tu participación en este servicio. {quien_cubre}, quien te cubría, también queda desafectado/a.","cierre":"Si tenés dudas, respondé a este correo.","footer":"Orquesta Filarmónica de Río Negro – Sistema de Gestión"}'::jsonb),
