  ('viaticos_simple', '', 'Viáticos individuales', 'Viáticos OFRN | {gira}', '{"saludo":"Hola {nombre}, ¿cómo estás?","intro":"Te comparto cómo serán los viáticos para esta gira (<strong>{gira}</strong>):","aclaracion_comidas":"El monto destinado a <span style=\"color:#15803d;font-weight:bold\">comidas</span> no se rinde, por lo cual no necesitas guardar los tickets.","aclaracion_rendibles":"El monto destinado a movilidad (pasajes) sí se rinde, así que debes conservar los pasajes y enviarlos firmados a filarmonica.scrn@gmail.com. En caso de gastar menos que el monto estimado deberás devolver la diferencia; y si gastaras más, se reintegrará el excedente.","cierre":"Nos mantenemos en contacto.<br>¡Beso y buena semana!","firma_nombre":"Carla Fernández","firma_cargo":"Administración","firma_org":"Orquesta Filarmónica de Río Negro"}'::jsonb),
  ('confirmacion_comidas', '', 'Confirmación de comidas', 'Confirmación de Comidas | {gira}', '{"saludo":"Hola,","intro":"Está abierta la confirmación de comidas para la gira <strong>{nomenclador} - {gira}</strong>.","aviso_fecha":"⚠️ La misma se encontrará abierta hasta el <strong>{fecha_limite}</strong>.","cuerpo":"<strong>La confirmación es fundamental</strong> para poder garantizar que se dispondrá de las comidas necesarias para cada participante de la gira.","firma_nombre":"Carla Fernández","firma_cargo":"Administración","firma_org":"Orquesta Filarmónica de Río Negro"}'::jsonb),
