-- Plantillas de mail editables desde Gestión (textos; layout fijo en EF).
CREATE TABLE IF NOT EXISTS public.mail_plantillas (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  template_id text NOT NULL,
  variant_key text NOT NULL DEFAULT '',
  titulo text NOT NULL,
  asunto text NOT NULL DEFAULT '',
  slots jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by bigint NULL,
  CONSTRAINT mail_plantillas_template_variant_uidx UNIQUE (template_id, variant_key),
  CONSTRAINT mail_plantillas_slots_object CHECK (jsonb_typeof(slots) = 'object')
);

COMMENT ON TABLE public.mail_plantillas IS
  'Textos editables de mails_produccion (asunto + slots). El HTML/layout vive en la Edge Function.';

CREATE INDEX IF NOT EXISTS mail_plantillas_template_idx
  ON public.mail_plantillas (template_id);

-- Sin RLS (patrón OFRN en tablas de gestión).
ALTER TABLE public.mail_plantillas DISABLE ROW LEVEL SECURITY;

GRANT SELECT, INSERT, UPDATE, DELETE ON public.mail_plantillas
  TO authenticated, anon, service_role;
GRANT USAGE, SELECT ON SEQUENCE public.mail_plantillas_id_seq
  TO authenticated, anon, service_role;

ON CONFLICT (template_id, variant_key) DO UPDATE SET
  titulo = EXCLUDED.titulo,
  asunto = EXCLUDED.asunto,
  slots = EXCLUDED.slots,
  updated_at = now();
